{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-0QjVJo/src/address.js","content":"/**
 * Cell address parsing and column arithmetic.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Convert a 1-2 letter column name to its 1-based number (A=1, Z=26, AA=27, ZZ=702). */
export function columnToNumber(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** Convert a 1-based column number back to its letters. */
export function numberToColumn(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parse a raw address token (already known to be a "word": letters then
 * optional digits, case-insensitive). Returns null when it is not a valid,
 * addressable cell (wrong shape, or row 0).
 */
export function parseAddress(raw) {
  const m = ADDRESS_RE.exec(raw)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const digits = m[2]
  const row = parseInt(digits, 10)
  if (row < 1) return null
  const col = columnToNumber(letters)
  return { address: letters + digits, col, row }
}

/** Compare two addresses for the canonical ascending-column-then-row order. */
export function compareAddresses(a, b) {
  const pa = parseAddress(a)
  const pb = parseAddress(b)
  if (pa.col !== pb.col) return pa.col - pb.col
  return pa.row - pb.row
}
"}

