 * Turn a formula body into a list of tokens. Throws LexError on any
 * character the grammar does not know about.
 */
export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      if (j < n && src[j] === '.' && j + 1 < n && src[j + 1] >= '0' && src[j + 1] <= '9') {
        j++
        while (j < n && src[j] >= '0' && src[j] <= '9') j++
      }
      tokens.push({ type: 'NUMBER', value: src.slice(i, j) })
      i = j
      continue
    }
    if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
      let j = i + 1
      while (j < n && ((src[j] >= 'A' && src[j] <= 'Z') || (src[j] >= 'a' && src[j] <= 'z'))) j++
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      tokens.push({ type: 'IDENT', value: src.slice(i, j) })
      i = j
      continue
    }
    if (ch === '<') {
      if (src[i + 1] === '>') {
        tokens.push({ type: 'OP', value: '<>' })
        i += 2
        continue
      }
      if (src[i + 1] === '=') {
        tokens.push({ type: 'OP', value: '<=' })
        i += 2
        continue
      }
      tokens.push({ type: 'OP', value: '<' })
      i++
      continue
