{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-0QjVJo/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies. Produces an AST or throws
 * ParseError; the caller treats a parse failure as the #ERR! value.
 */

import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const CALL_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  at(type, value) {
    const t = this.peek()
    if (t.type !== type) return false
    if (value !== undefined && t.value.toUpperCase() !== value) return false
    return true
  }

  consume() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.peek()
    if (t.type !== type) throw new ParseError(`expected ${type}, got ${t.type}`)
    return this.consume()
  }

  parseFormula() {
    const expr = this.parseExpr()
    this.expect('EOF')
    return expr
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek().type === 'OP' && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.consume().value
      const right = this.parseAdditive()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseTerm()
    while (this.peek().type === 'OP' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.consume().value
      const right = this.parseTerm()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseTerm() {
    let left = this.parsePower()
    while (this.peek().type === 'OP' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.consume().value
      const right = this.parsePower()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek().type === 'OP' && this.peek().value === '^') {
      this.consume()
      const right = this.parsePower()
      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek().type === 'OP' && (this.peek().value === '-' || this.peek().value === '+')) {
      const op = this.consume().value
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parseAtom()
  }

  parseAtom() {
    const t = this.peek()
    if (t.type === 'NUMBER') {
      this.consume()
      return { type: 'number', value: parseFloat(t.value) }
    }
    if (t.type === 'LPAREN') {
      this.consume()
      const e = this.parseExpr()
      this.expect('RPAREN')
      return e
    }
    if (t.type === 'IDENT') {
      const upper = t.value.toUpperCase()
      if (upper === 'TRUE' || upper === 'FALSE') {
        this.consume()
        return { type: 'bool', value: upper === 'TRUE' }
      }
      if (this.peek(1) && this.peek(1).type === 'LPAREN') {
        this.consume() // ident
        this.consume() // (
        const args = []
        if (!this.at('RPAREN')) {
          args.push(this.parseArg())
          while (this.at('COMMA')) {
            this.consume()
            args.push(this.parseArg())
          }
        }
        this.expect('RPAREN')
        return { type: 'call', name: upper, args }
      }
      this.consume()
      return { type: 'address', raw: t.value }
    }
    throw new ParseError(`unexpected token ${t.type}`)
  }

  isRangeAhead() {
    const t0 = this.peek(0)
    const t1 = this.peek(1)
    const t2 = this.peek(2)
    if (!t0 || t0.type !== 'IDENT') return false
    const u0 = t0.value.toUpperCase()
