 * Value representation: a value is a number, text, a boolean, or an error.
 */

export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function num(value) {
  return { type: 'number', value }
}
export function text(value) {
  return { type: 'text', value }
}
export function bool(value) {
  return { type: 'bool', value }
}
export function err(token) {
  return { type: 'error', value: token }
}

export const DIV0 = err('#DIV/0!')
export const REF = err('#REF!')
export const VALUE_ERR = err('#VALUE!')
export const CYCLE = err('#CYCLE!')
export const NAME_ERR = err('#NAME?')
export const GENERIC_ERR = err('#ERR!')

/** Wrap a raw JS number result of arithmetic, turning non-finite into #DIV/0!. */
export function wrapNumber(x) {
  if (!Number.isFinite(x)) return DIV0
  return num(x)
}

/** Read a value as a number for arithmetic purposes. */
export function toNumber(v) {
  if (v.type === 'number') return v
  if (v.type === 'bool') return num(v.value ? 1 : 0)
  if (v.type === 'text') return VALUE_ERR
  return v // error passes through
}

function kindRank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2 // bool
}

/** Compare two non-error values per the spec's total order. Returns -1/0/1. */
export function compareValues(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.type === 'number') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  // bool: false below true
  const av = a.value ? 1 : 0
  const bv = b.value ? 1 : 0
  return av < bv ? -1 : av > bv ? 1 : 0
}
"}

