import { parseAddress } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * Parse the sheet text into an ordered Map from canonical address to
 * { content, line }. Throws SheetError on the first invalid line.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const m = /^[^ \t]+/.exec(stripped)
    const addrRaw = m[0]
    let rest = stripped.slice(addrRaw.length)
    rest = rest.replace(/^[ \t]+/, '')
    const content = rest

    const parsed = parseAddress(addrRaw)
    if (!parsed) {
      throw new SheetError(lineNum, `invalid cell address ${addrRaw}`)
    }
    if (cells.has(parsed.address)) {
      throw new SheetError(lineNum, `cell ${parsed.address} is declared twice`)
    }
    cells.set(parsed.address, { content, line: lineNum, col: parsed.col, row: parsed.row })
  }

  return cells
}
