 * Evaluation of a sheet: literals, formulas, cell references, ranges,
 * operators, functions, and cycle/dependency tracking.
 */

import { parseAddress, compareAddresses } from './address.js'
import { parseFormula, CALL_NAMES } from './parser.js'
import {
  num,
  text,
  bool,
  err,
  ERROR_TOKENS,
  DIV0,
  REF,
  VALUE_ERR,
  CYCLE,
  NAME_ERR,
  GENERIC_ERR,
  wrapNumber,
  toNumber,
  compareValues,
} from './values.js'

const NUMBER_LITERAL_RE = /^-?[0-9]+(\.[0-9]+)?$/

export function parseLiteral(content) {
  if (content === '') return num(0)
  if (ERROR_TOKENS.has(content)) return err(content)
  if (NUMBER_LITERAL_RE.test(content)) return num(parseFloat(content))
  return text(content)
}

/** Expand a range's two corner addresses into an ordered list of addresses. */
function expandRange(fromRaw, toRaw) {
  const from = parseAddress(fromRaw)
  const to = parseAddress(toRaw)
  if (!from || !to) return null
  const c0 = Math.min(from.col, to.col)
  const c1 = Math.max(from.col, to.col)
  const r0 = Math.min(from.row, to.row)
  const r1 = Math.max(from.row, to.row)
  const cells = []
  for (let c = c0; c <= c1; c++) {
    for (let r = r0; r <= r1; r++) {
      // Reconstruct the column letters from the numeric value.
      cells.push(colRowToAddress(c, r))
    }
  }
  return cells
}

function colRowToAddress(col, row) {
  let s = ''
  let n = col
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s + String(row)
}

export class Sheet {
  constructor(cells) {
    this.cells = cells // Map address -> { content, line }
    this.asts = new Map() // address -> ast | null (parsed once)
    this.results = new Map() // address -> Value (final)
    this.state = new Map() // address -> 'computing' | 'done'
    this.stack = []
  }

  getAst(address) {
    if (this.asts.has(address)) return this.asts.get(address)
    const cell = this.cells.get(address)
    let ast = null
    if (cell.content.startsWith('=')) {
      ast = parseFormula(cell.content.slice(1))
    }
    this.asts.set(address, ast)
    return ast
  }

  getValue(address) {
    if (this.results.has(address)) return this.results.get(address)
    if (!this.cells.has(address)) return num(0)

    if (this.state.get(address) === 'computing') {
      const idx = this.stack.indexOf(address)
      for (let i = idx; i < this.stack.length; i++) {
        const a = this.stack[i]
        this.results.set(a, CYCLE)
        this.state.set(a, 'done')
      }
      return CYCLE
    }

    this.state.set(address, 'computing')
    this.stack.push(address)

    const value = this.computeValue(address)

    if (this.results.has(address)) {
      // A cycle was detected while computing this cell and it was already
      // forced to #CYCLE! by a deeper frame.
      this.state.set(address, 'done')
      this.stack.pop()
      return this.results.get(address)
    }

    this.results.set(address, value)
    this.state.set(address, 'done')
    this.stack.pop()
    return value
  }

  computeValue(address) {
    const cell = this.cells.get(address)
    if (!cell.content.startsWith('=')) {
      return parseLiteral(cell.content)
    }
    const ast = this.getAst(address)
    if (!ast) return GENERIC_ERR
    return this.evalExpr(ast)
  }

  evalExpr(node) {
    switch (node.type) {
      case 'number':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'address': {
        const parsed = parseAddress(node.raw)
        if (!parsed) return REF
        return this.getValue(parsed.address)
      }
      case 'unary': {
        const operand = this.evalExpr(node.operand)
        if (operand.type === 'error') return operand
        const n = toNumber(operand)
        if (n.type === 'error') return n
        const v = node.op === '-' ? -n.value : n.value
        return wrapNumber(v)
      }
      case 'binop':
        return this.evalBinOp(node)
      case 'call':
        return this.evalCall(node)
      case 'range':
        // A range outside of a direct function-argument position is a
        // grammar failure, so the parser never produces this here.
        return GENERIC_ERR
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  evalBinOp(node) {
    const left = this.evalExpr(node.left)
    const right = this.evalExpr(node.right)
    if (left.type === 'error') return left
    if (right.type === 'error') return right

    const op = node.op
    if (op === '+' || op === '-' || op === '*' || op === '/' || op === '^') {
      const a = toNumber(left)
      if (a.type === 'error') return a
      const b = toNumber(right)
      if (b.type === 'error') return b
      switch (op) {
        case '+':
          return wrapNumber(a.value + b.value)
        case '-':
          return wrapNumber(a.value - b.value)
        case '*':
          return wrapNumber(a.value * b.value)
        case '/':
          if (b.value === 0) return DIV0
          return wrapNumber(a.value / b.value)
        case '^':
          return wrapNumber(Math.pow(a.value, b.value))
      }
    }

    // comparisons
    const cmp = compareValues(left, right)
    switch (op) {
      case '=':
        return bool(cmp === 0)
      case '<>':
        return bool(cmp !== 0)
      case '<':
        return bool(cmp < 0)
      case '<=':
        return bool(cmp <= 0)
      case '>':
        return bool(cmp > 0)
      case '>=':
        return bool(cmp >= 0)
      default:
        throw new Error(`unknown operator ${op}`)
    }
  }

  /** Flatten one call argument into a list of values (ranges expanded). */
  flattenArg(arg) {
    if (arg.type === 'range') {
      const cells = expandRange(arg.from, arg.to)
      if (!cells) return [REF]
      return cells.map((a) => this.getValue(a))
    }
    return [this.evalExpr(arg)]
  }

  evalCall(node) {
    const name = node.name
    if (name === 'IF') {
      if (node.args.length !== 3) return GENERIC_ERR
      const condVals = this.flattenArg(node.args[0])
      const condErr = condVals.find((v) => v.type === 'error')
      if (condErr) return condErr
      const condVal = condVals[0]
      const cond = this.toBoolean(condVal)
      if (cond.type === 'error') return cond
      const branch = cond.value ? node.args[1] : node.args[2]
      const vals = this.flattenArg(branch)
      const bErr = vals.find((v) => v.type === 'error')
      if (bErr) return bErr
      return vals[0]
    }

    if (!CALL_NAMES.has(name)) return NAME_ERR

    if (name === 'ABS' && node.args.length !== 1) return GENERIC_ERR
    if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name) && node.args.length < 1) {
      return GENERIC_ERR
    }

    const values = []
    for (const arg of node.args) {
      values.push(...this.flattenArg(arg))
    }

    const firstError = values.find((v) => v.type === 'error')
    if (firstError) return firstError

    if (name === 'COUNT') {
      const count = values.filter((v) => v.type === 'number').length
      return num(count)
    }

    const nums = []
    for (const v of values) {
      const n = toNumber(v)
      if (n.type === 'error') return n
      nums.push(n.value)
    }

    switch (name) {
      case 'SUM':
        return wrapNumber(nums.reduce((a, b) => a + b, 0))
      case 'MIN':
        return wrapNumber(Math.min(...nums))
      case 'MAX':
        return wrapNumber(Math.max(...nums))
      case 'AVG':
        return wrapNumber(nums.reduce((a, b) => a + b, 0) / nums.length)
      case 'ABS':
        return wrapNumber(Math.abs(nums[0]))
      default:
        throw new Error(`unhandled function ${name}`)
    }
  }

  toBoolean(v) {
    if (v.type === 'bool') return v
    if (v.type === 'number') return bool(v.value !== 0)
    if (v.type === 'text') return VALUE_ERR
    return v
  }
}

/** Collect every address a formula's AST directly names (ranges expanded). */
export function collectDeps(ast) {
  const set = new Set()
  function walkArg(arg) {
    if (arg.type === 'range') {
      const cells = expandRange(arg.from, arg.to)
      if (cells) for (const c of cells) set.add(c)
      return
    }
    walk(arg)
  }
  function walk(node) {
    switch (node.type) {
      case 'number':
      case 'bool':
        return
      case 'address': {
        const parsed = parseAddress(node.raw)
        if (parsed) set.add(parsed.address)
        return
      }
      case 'unary':
        walk(node.operand)
        return
      case 'binop':
        walk(node.left)
        walk(node.right)
        return
      case 'call':
        for (const a of node.args) walkArg(a)
        return
      case 'range':
        walkArg(node)
        return
      default:
        return
    }
  }
  walk(ast)
  return Array.from(set).sort(compareAddresses)
}
"}

